contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable {
        require(dummy == dummy);
        uint256 beforeSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.owned(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;

        assert(!reverted && afterOwner == address(this) && afterSupply == beforeSupply);
    }

    receive() external payable {}
}

