pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy == dummy);
        uint256 beforeSupply;
        try c.totalSupply() returns (uint256 __r) { beforeSupply = __r; } catch { return; }
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        bool reverted;
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterSupply;
        try c.totalSupply() returns (uint256 __r) { afterSupply = __r; } catch { return; }
        address afterOwner;
        try c.owner() returns (address __r) { afterOwner = __r; } catch { return; }
        assertTrue(!reverted && afterOwner == address(this) && afterSupply == beforeSupply);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
